// Verifies the request actually came from HubSpot (HubSpot Signature v3).
// Requires: Webhook node option "Raw Body" = true, and an n8n environment
// variable HUBSPOT_CLIENT_SECRET holding the HubSpot app's client secret.
const crypto = require('crypto');

const input = $input.first().json;
const headers = input.headers || {};
const rawBody = input.rawBody || JSON.stringify(input.body);

const signature = headers['x-hubspot-signature-v3'];
const timestamp = headers['x-hubspot-request-timestamp'];
const clientSecret = '0f39ee21-4072-44e4-b215-a2cf0caf3d8a';

let valid = false;
let reason = '';

if (!clientSecret) {
  reason = 'HUBSPOT_CLIENT_SECRET is not configured on this n8n instance';
} else if (!signature || !timestamp) {
  reason = 'Missing signature or timestamp header';
} else if (Math.abs(Date.now() - Number(timestamp)) > 5 * 60 * 1000) {
  reason = 'Timestamp too old - possible replay';
} else {
  const method = 'POST';
  const url = 'https://' + (headers['x-forwarded-host'] || headers.host) + '/webhook/trigger-reengagement';
  const base = method + url + rawBody + timestamp;
  const expected = crypto.createHmac('sha256', clientSecret).update(base).digest('base64');
  if (signature.length === expected.length) {
    valid = crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
  }
  if (!valid) reason = 'Signature mismatch';
}

return [{ json: { ...input, signature_valid: valid, signature_invalid_reason: reason } }];

const events = $input.first().json.body;

if (!Array.isArray(events)) {
  return [{ json: { skip: true, reason: "Unexpected payload shape" } }];
}

return events
  .filter(e => e.propertyName === 'trigger_re_engagement' && e.propertyValue === 'true')
  .map(e => ({ json: e }));

const event = $('If: Has Events To Process1').first().json;
const hs = $('HubSpot: Get Contact by ID1').first().json;
let reason = 'Contact fetch failed - possibly deleted or inaccessible after retries';
