const val = (p) => (p && typeof p === 'object' ? p.value : p) || '';

const email = val(props.email);
const campaignSegment = val(props.campaign_segment);

const campaignIdMap = {
  'Dropometer reengagement': 'dropometer_reengagement_v1',
  'Educational reengagement': 'educational_reengagement_v1',
