};
const campaignId = campaignIdMap[campaignSegment] || campaignSegment.toLowerCase().replace(/\s+/g, '_');

const cooldownDays = Number($('Config: Load Constants1').first().json.cooldownDays || 90);
const now = Date.now();

// Only rows for THIS contact + THIS campaign, that were actually Sent
const rows = $input.all().map(i => i.json).filter(r =>
  r['Contact Email'] === email &&
  r['Status'] === 'Sent' &&
  (r['Campaign ID'] ? r['Campaign ID'] === campaignId : r['Campaign Segment'] === campaignSegment)
);

let inCooldown = false;
let mostRecent = null;

for (const row of rows) {
  const createdAt = row['Created At'] ? new Date(row['Created At']).getTime() : null;
  if (createdAt && !isNaN(createdAt) && (!mostRecent || createdAt > mostRecent)) {
    mostRecent = createdAt;
  }
}

if (mostRecent) {
  const daysSince = (now - mostRecent) / (1000 * 60 * 60 * 24);
  if (daysSince < cooldownDays) inCooldown = true;
}

return [{
  json: {
    contactId: $('HubSpot: Get Contact by ID1').first().json.vid,
    portalId: $('HubSpot: Get Contact by ID1').first().json['portal-id'],
