    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/\r/g, '');
}
function cleanText(text) {
  return String(text)
    .replace(/https?:\/\/\S+/gi, ' ')
    .replace(/^>.*$/gm, '')
