const json = $input.first().json;
let text = "";

if (typeof json.text === 'string') {
    text = json.text;
} else if (typeof json.content === 'string') {
    text = json.content;
} else if (Array.isArray(json.content) && json.content.length > 0 && json.content[0].text) {
    text = json.content[0].text;
} else if (json.message?.content) {
    text = typeof json.message.content === 'string' ? json.message.content : (json.message.content[0]?.text || "");
} else if (Array.isArray(json) && json[0]?.text) {
    text = json[0].text;
} else if (json.kwargs?.content) {
    text = json.kwargs.content;
}

let data;
let parseSucceeded = true;
let parseError = '';

try {
  if (!text) throw new Error("Could not find Claude's text in the payload");
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end >= start) {
    data = JSON.parse(text.substring(start, end + 1));
  } else {
    throw new Error("No JSON object found inside the text");
  }
  if (!data.summary?.trim() || !data.draft_email?.trim()) {
    throw new Error("Parsed JSON missing required fields (summary/draft_email)");
  }
  if (data.draft_email.trim().length < 20) {
    throw new Error("draft_email is too short to be a real email (business validation failed)");
  }
} catch (e) {
  parseSucceeded = false;
  parseError = e.message;
  data = { summary: '', issues: [], draft_email: '', suggested_status: 'Error', updated_context_summary: '', updated_personalisation_hook: '' };
}

const eligibility = $('Code: Eligibility Gate1').first().json;
const promptData = $('Code: Build Segment Prompt1').first().json;

let threadId = null;
try { threadId = $('Get a message1').first().json.threadId; } catch (e) {}
if (!threadId) { try { threadId = $('Get a message (New Only)1').first().json.threadId; } catch (e) {} }

return [{
  json: {
    parse_succeeded: parseSucceeded,
    parse_error: parseError,
    email: eligibility.email,
    context_mode: json.context_mode || '',
    contactId: eligibility.contactId,
    portalId: eligibility.portalId,
    segment: eligibility.segment,
    campaign_segment: eligibility.campaign_segment,
    campaignId: promptData.campaignId,
    executionId: promptData.executionId,
    idempotencyKey: promptData.idempotencyKey,
    summary: data.summary,
    issues: Array.isArray(data.issues) ? data.issues.join(', ') : (data.issues || ''),
    draft_email: data.draft_email,
    suggested_status: data.suggested_status || 'Needs Review',
    updated_context_summary: data.updated_context_summary?.trim() || eligibility.ai_context_summary || '',
    updated_personalisation_hook: data.updated_personalisation_hook?.trim() || eligibility.ai_personalisation_hook || '',
    tokens_used: json.usage || { input_tokens: 0, output_tokens: 0 },
    thread_link: threadId ? `https://mail.google.com/mail/u/0/#inbox/${threadId}` : 'No thread found'
  }
}];

const d = $('Code: Parse AI Output1').first().json;
return [{
  json: {
    timestamp: new Date().toISOString(),
    contact_email: d.email,
    hubspot_contact_id: d.contactId,
    segment: d.segment,
    campaign_segment: d.campaign_segment,
    skip_reason: `AI response parsing failed: ${d.parse_error}`,
    failed_step: 'Code: Parse AI Output'
  }
}];

const hsData = $input.first().json;
const props = hsData.properties || {};

const val = (p) => {
  if (p && typeof p === 'object') {
    return p.value ?? '';
  }
  return p ?? '';
};

const toBool = (p) => {
  return String(val(p)).toLowerCase() === 'true';
};

const segment = val(props.segment);
const campaignSegment = val(props.campaign_segment);
const eligibilityReason = val(props.campaign_eligibility_reason);

const reengagementCampaigns = [
  'Dropometer reengagement',
  'Educational reengagement'
];

// ============================================================
// FINAL-SEND SUPPRESSION CHECKS
// ============================================================

const optedOut = toBool(props.unsubscribed_from_all_email);
const badEmail = toBool(props.invalid_email_address);
const globallyIneligible = toBool(props.is_globally_ineligible);

// ============================================================
// LIVE ELIGIBILITY
// ============================================================

let eligible = true;
let reason = '';

if (!props.email) {
  eligible = false;
  reason = 'Contact could not be re-fetched from HubSpot (deleted or inaccessible)';
}
else if (!campaignSegment || campaignSegment === 'Not eligible') {
  eligible = false;
  reason = `campaign_segment is now empty or "Not eligible" (value: "${campaignSegment}")`;
}
else if (eligibilityReason !== 'Eligible') {
  eligible = false;
  reason = `campaign_eligibility_reason is now not "Eligible" (value: "${eligibilityReason}")`;
}
else if (segment === 'Partner' && reengagementCampaigns.includes(campaignSegment)) {
  eligible = false;
  reason = 'Partner contacts are excluded from re-engagement campaigns';
}
else if (optedOut) {
  eligible = false;
  reason = 'Contact has unsubscribed from all email';
}
else if (badEmail) {
  eligible = false;
  reason = 'Email address is invalid';
}
else if (globallyIneligible) {
  eligible = false;
  reason = 'Contact is globally ineligible';
}

// ============================================================
// ORIGINAL REVIEW BOARD ROW
// Preserve IDs generated in Flow A.
// ============================================================

const triggerRow = $('Google Sheets Trigger: Watch Review Board1').first().json;

// ============================================================
// OUTPUT
// ============================================================

return [{
  json: {
    email: val(props.email),
    contactId: triggerRow['ID'] || '',
    segment,
    campaign_segment: campaignSegment,
    campaignId: triggerRow['Campaign ID'] || '',
    executionId: triggerRow['Execution ID'] || '',
    idempotencyKey: triggerRow['Idempotency Key'] || '',
    eligible,
    reason
  }
}];

