if (existing) {
  const lastSeen = existing['Last Seen'] ? new Date(existing['Last Seen']).getTime() : 0;
  const minutesSince = (now - lastSeen) / (1000 * 60);
  firstSeen = existing['First Seen'] || firstSeen;
  count = (Number(existing['Count']) || 0) + 1;
  sendAlert = minutesSince > cooldownMinutes;
}

return [{ json: { ...sig, first_seen: firstSeen, last_seen: new Date().toISOString(), count, send_alert: sendAlert } }];

